def transform(grid):
    from collections import Counter

    out = [row[:] for row in grid]
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    points = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row)
              if v != background]
    if not points:
        return out

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if r in (r0, r1) or c in (c0, c1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
